package com.bank.authstream.producer;

import org.apache.kafka.clients.producer.KafkaProducer;
import org.apache.kafka.clients.producer.ProducerRecord;
import org.springframework.stereotype.Component;
import lombok.extern.slf4j.Slf4j;

@Component
@Slf4j
public class AuthEventProducer {

    private final KafkaProducer<String, String> producer;

    public AuthEventProducer(KafkaProducer<String, String> producer) { this.producer = producer; }

    // Many small sends are batched by the client into large sequential appends on the broker.
    public void publishAuth(String cardId, String payload) {
        producer.send(new ProducerRecord<>("card.auth", cardId, payload));
        // No flush per record: batching + OS page cache turn these into big sequential writes.
    }
}
