// ─── File: demo/ThroughputDemo.java ───
package com.bank.authstream.demo;

import java.util.logging.ConsoleHandler;
import java.util.logging.Formatter;
import java.util.logging.Level;
import java.util.logging.LogRecord;
import java.util.logging.Logger;

public class ThroughputDemo {

    private static final Logger log = Logger.getLogger(ThroughputDemo.class.getName());

    static {
        Logger root = Logger.getLogger("");
        for (var h : root.getHandlers()) root.removeHandler(h);
        ConsoleHandler handler = new ConsoleHandler();
        handler.setFormatter(new BankLogFormatter());
        root.addHandler(handler);
        root.setLevel(Level.INFO);
    }

    public static void main(String[] args) {
        int records = 1_000_000;

        log.info("=== Pillar 1: sequential append vs random I/O ===");
        WritePattern seq = new WritePattern(/*sequential*/ true);
        WritePattern rnd = new WritePattern(/*sequential*/ false);
        long seqMs = seq.writeCostMs(records);
        long rndMs = rnd.writeCostMs(records);
        log.info("sequential append: " + seqMs + " ms  | random I/O: " + rndMs + " ms  (="
                + (rndMs / Math.max(1, seqMs)) + "x slower)");

        log.info("=== Pillar 2: zero-copy sendfile vs user-space copy ===");
        TransferPath naive = new TransferPath(false);
        TransferPath zeroCopy = new TransferPath(true);
        log.info("user-space read: copies=" + naive.copies() + " ctxSwitches=" + naive.contextSwitches());
        log.info("zero-copy sendfile: copies=" + zeroCopy.copies() + " ctxSwitches=" + zeroCopy.contextSwitches()
                + " (bytes go page-cache -> socket directly, heap untouched)");

        log.info("=== Pillar 3: OS page cache for tail reads ===");
        PageCache cache = new PageCache();
        int tailHits = cache.simulateReads(/*tailReads*/ 900_000, /*oldReads*/ 100_000);
        log.info("tail reads served from RAM (page cache hits) = " + tailHits
                + " of 1,000,000; small JVM heap => short GC pauses");
    }
}

// ─── Would be in WritePattern.java in a real project ───
class WritePattern {
    private final boolean sequential;
    WritePattern(boolean sequential) { this.sequential = sequential; }
    // Sequential: ~1 unit per record (coalesced). Random: ~40 units (seek + RMW).
    long writeCostMs(int records) {
        long perRecordMicros = sequential ? 1 : 40;
        return records * perRecordMicros / 1000;
    }
}

// ─── Would be in TransferPath.java in a real project ───
class TransferPath {
    private final boolean zeroCopy;
    TransferPath(boolean zeroCopy) { this.zeroCopy = zeroCopy; }
    // Naive: page cache -> app buffer -> socket buffer -> NIC (4 copies).
    // Zero-copy: page cache -> NIC via sendfile (effectively 1, no user-space copy).
    int copies() { return zeroCopy ? 1 : 4; }
    int contextSwitches() { return zeroCopy ? 2 : 4; }
}

// ─── Would be in PageCache.java in a real project ───
class PageCache {
    // Tail reads (recent data) are almost always in the page cache; old reads may miss.
    int simulateReads(int tailReads, int oldReads) {
        int hits = tailReads;                 // tail is hot in cache
        hits += (int) (oldReads * 0.2);       // some old data still cached
        return hits;
    }
}

// ─── Would be in BankLogFormatter.java in a real project ───
class BankLogFormatter extends Formatter {
    public String format(LogRecord r) {
        return String.format("[%1$tF %1$tT] [%2$s] %3$s%n",
                new java.util.Date(r.getMillis()), r.getLevel(), formatMessage(r));
    }
}
